// mid-round carrier switch cannot leave residual text on the abandoned sink.
@Volatile private var lastActive: VoiceSessionManager.BubbleSink? = null

private fun active(): VoiceSessionManager.BubbleSink {
    val target = if (carrier() == ReplyCarrier.FULLSCREEN) fullscreen else overlay
    if (target !== lastActive) {
        lastActive?.hide()
        lastActive = target
    }
    return target
}

override fun hideLater(delayMs: Long) {
    // Scheduled side effects are not re-routed on a mid-round switch: the timer still
    // fires on the previously chosen sink. Ensure that sink's show()/hide() cancels
