fun feed(pcmBytes: ByteArray): Event? {
    if (!isActive || pcmBytes.size < 2) return null // 空闲时不做解码；截断尾块交上层处理
    require(pcmBytes.size % 2 == 0) { "Int16 PCM 字节数必须为偶数" }
    val samples = ShortArray(pcmBytes.size / 2) { i ->
        ((pcmBytes[2 * i].toInt() and 0xFF) or
            ((pcmBytes[2 * i + 1].toInt() and 0xFF) shl 8)).toShort()
    }
    return feed(samples)
}
